// Pure helpers for viewport chunk loading, including signed infinite-world chunks.
export function chunkKey(cx,cy){return cx+':'+cy;}
export function parseChunkKey(key){const i=String(key).indexOf(':');if(i<0)return null;const x=Number(String(key).slice(0,i)),y=Number(String(key).slice(i+1));if(!Number.isFinite(x)||!Number.isFinite(y))return null;return{x,y};}
export function centerChunk(view,size){const{offsetX,offsetY,scale,viewW,viewH}=view;if(!scale||!size)return{cx:0,cy:0};return{cx:Math.floor(((viewW/2-offsetX)/scale)/size),cy:Math.floor(((viewH/2-offsetY)/scale)/size)};}
export function viewportChunkRange(view,size,margin=1){const{offsetX,offsetY,scale,viewW,viewH}=view;if(!scale||!size||!viewW||!viewH)return{x0:0,y0:0,x1:0,y1:0};const span=size*scale;return{x0:Math.floor(-offsetX/span)-margin,y0:Math.floor(-offsetY/span)-margin,x1:Math.floor((viewW-offsetX)/span)+margin,y1:Math.floor((viewH-offsetY)/span)+margin};}
export function rangeKeys(range){const keys=[];for(let y=range.y0;y<=range.y1;y++)for(let x=range.x0;x<=range.x1;x++)keys.push(chunkKey(x,y));return keys;}
export function rangeSize(range){return Math.max(0,range.x1-range.x0+1)*Math.max(0,range.y1-range.y0+1);}
export function ringKeys(cx,cy,radius){const keys=[];for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){if(Math.max(Math.abs(dx),Math.abs(dy))!==radius)continue;keys.push(chunkKey(cx+dx,cy+dy));}return keys;}
export function missingRadius(cx,cy,loaded,maxRadius){for(let radius=0;radius<=maxRadius;radius++){const keys=ringKeys(cx,cy,radius);if(keys.some((key)=>!loaded.has(key)))return radius;}return-1;}
export function planRequests(range,loaded,center,maxRadius=2){const radius=Math.max(0,Math.trunc(maxRadius)),step=radius*2+1,has=(key)=>!!(loaded&&loaded.has&&loaded.has(key)),plans=[];const bx0=Math.floor(range.x0/step),bx1=Math.floor(range.x1/step),by0=Math.floor(range.y0/step),by1=Math.floor(range.y1/step);for(let by=by0;by<=by1;by++)for(let bx=bx0;bx<=bx1;bx++){const cx=bx*step+radius,cy=by*step+radius,missing=[];for(let y=Math.max(range.y0,cy-radius);y<=Math.min(range.y1,cy+radius);y++)for(let x=Math.max(range.x0,cx-radius);x<=Math.min(range.x1,cx+radius);x++){const key=chunkKey(x,y);if(!has(key))missing.push(key);}if(!missing.length)continue;const dx=cx-(center?.cx??cx),dy=cy-(center?.cy??cy);plans.push({cx,cy,radius,keys:missing,distance:Math.max(Math.abs(dx),Math.abs(dy))});}return plans.sort((a,b)=>a.distance-b.distance);}
